#!/usr/bin/env python3
"""Build public pages without case-specific financial data; Python standard library only."""
from html import escape
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
PAGES = ROOT / 'pages'
PAGES.mkdir(exist_ok=True)
S = {
 'irs': ('IRS: estate and gift tax', 'https://www.irs.gov/businesses/small-businesses-self-employed/whats-new-estate-and-gift-tax'),
 'basis': ('IRS: inherited property basis', 'https://www.irs.gov/faqs/interest-dividends-other-types-of-income/gifts-inheritances/gifts-inheritances'),
 'estate': ('IRS: estate tax', 'https://www.irs.gov/businesses/small-businesses-self-employed/estate-tax'),
 'boe': ('California BOE: Proposition 19', 'https://www.boe.ca.gov/Prop19/'),
 'cap': ('California BOE: adjusted Proposition 19 amount', 'https://www.boe.ca.gov/news/2025/nr-25-02.htm'),
 'prop13': ('California BOE: property tax overview', 'https://www.boe.ca.gov/proptaxes/pdf/pub29.pdf'),
 'ca': ('California FTB: gifts and inheritance', 'https://www.ftb.ca.gov/file/personal/income-types/gifts-and-inheritance.html'),
 'pickup': ('California FTB: estate pick-up tax analysis (2017)', 'https://www.ftb.ca.gov/tax-pros/law/legislation/2017-2018/sb726-032317.pdf'),
 'gain': ('California FTB: capital gains', 'https://www.ftb.ca.gov/file/personal/income-types/capital-gains-and-losses.html'),
 'ins': ('California Department of Insurance: market snapshot', 'https://www.insurance.ca.gov/01-consumers/180-climate-change/sustainable-insurance-strategy.Cfm'),
 'insdata': ('California Department of Insurance: residential data', 'https://www.insurance.ca.gov/0400-news/0200-studies-reports/0250-homeowners-study/'),
 'solar': ('California PUC: solar net billing', 'https://www.cpuc.ca.gov/industries-and-topics/electrical-energy/demand-side-management/customer-generation/net-energy-metering-and-net-billing'),
 'rent': ('San Francisco Rent Board: current rates and proposal', 'https://www.sf.gov/reports--current-rates-including-rent-increase-relocation-sec-deposit'),
 'rental': ('IRS: residential rental property', 'https://www.irs.gov/publications/p527'),
 'cpi': ('BLS: June 2022 inflation', 'https://www.bls.gov/opub/ted/2022/consumer-prices-up-9-1-percent-over-the-year-ended-june-2022-largest-increase-in-40-years.htm'),
 'cbo': ('CBO: long-term budget outlook', 'https://www.cbo.gov/publication/61187'),
 'fhfa': ('FHFA: house price index', 'https://www.fhfa.gov/data/hpi'),
 'trust': ('California Probate Code: trustee notice', 'https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?sectionNum=16061.7.&lawCode=PROB'),
 'income': ('IRS: net investment income tax', 'https://www.irs.gov/taxtopics/tc559'),
 'law': ('Congress: Public Law 119-21', 'https://www.congress.gov/119/plaws/publ21/PLAW-119publ21.pdf'),
 'vote': ('California Secretary of State: election results', 'https://electionresults.sos.ca.gov/'),
}
NAV = [('index','Overview'),('executive-summary','Executive summary'),('property-tax','Property tax'),('projections','Projections'),('operating-costs','Operating costs'),('inheritance-law','Estate & inheritance'),('estate-thresholds','Thresholds'),('decision-analysis','Decision analysis'),('black-swan-scenarios','Black-swan scenarios'),('inheritance-process','Inheritance process'),('law-watchlist','Law watchlist'),('methodology','Methodology'),('sources','Sources'),('flagged-for-review','Flagged for review'),('privacy','Privacy')]

def sources(keys):
    return ' · '.join(f'<a href="{escape(S[k][1], quote=True)}" rel="noopener noreferrer">{escape(S[k][0])}</a>' for k in keys)

def table(headers, rows):
    head=''.join('<th scope="col">'+escape(x)+'</th>' for x in headers)+ '<th scope="col">Official source</th>'
    body=''.join('<tr>'+''.join('<td>'+escape(str(x))+'</td>' for x in cells)+'<td>'+sources(keys)+'</td></tr>' for cells,keys in rows)
    return '<div class="tablewrap"><table><thead><tr>'+head+'</tr></thead><tbody>'+body+'</tbody></table></div>'

def page(slug,title,lead,body):
    sub=slug!='index'; root='../' if sub else ''
    nav=''.join(f'<a href="{root}{"index.html" if key=="index" else "pages/"+key+".html"}"'+(' aria-current="page"' if slug==key else '')+'>'+escape(label)+'</a>' for key,label in NAV)
    text=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="Privacy-first inheritance decision research"><title>{escape(title)} | Decision Brief</title><link rel="stylesheet" href="{root}assets/style.css"></head><body><header><div class="eyebrow">Private by design · Research brief</div><a href="{root}index.html">Inheritance Decision Brief</a></header><main class="shell"><nav aria-label="Sections">{nav}</nav><article><h1>{escape(title)}</h1><p class="lede">{escape(lead)}</p>{body}</article></main><footer>Research checked 11 November 2026. Laws and rates can change. Educational only; not legal, tax, investment or insurance advice.</footer></body></html>'''
    (ROOT/'index.html' if not sub else PAGES/(slug+'.html')).write_text(text,encoding='utf-8')

notice='<div class="notice"><strong>Privacy and verification first.</strong> This public site does not publish case-specific financial figures or dollar projections. Values that cannot be verified from official sources are blank; a source on a model row explains its context, not verification of the model inputs or prediction.</div>'
page('index','A clearer path forward','A source-linked guide to a future trust transfer and a separate, already-owned residence.',notice+'''<div class="card-grid"><div class="card"><span>Current federal basic exclusion</span><strong>$15,000,000</strong><span>2026; per decedent, subject to rules</span></div><div class="card"><span>Next decision</span><strong>Compare privately</strong><span>No defensible winner without verified inputs</span></div><div class="card"><span>Stress testing</span><strong>50 years</strong><span>Illustrative indices, not forecasts</span></div></div><h2>Start here</h2><p>The inherited home and the already-owned residence play different roles. Keeping the existing residence may preserve housing and rental income; inheritance of the other home may trigger a reassessment. Determine the transfer, occupancy and trust facts before choosing.</p>'''+table(['Priority','Action'],[(('1 · Establish facts','Privately verify title, trust terms, assessments, insurance, income and the entire estate.'),['boe','estate']),(('2 · Compare options','Calculate after-tax sell, rental and occupancy outcomes using the same time horizon.'),['basis','rental']),(('3 · Test shocks','Assess inflation, property downturns, market losses and liquidity needs.'),['cpi','fhfa'])]))
page('executive-summary','Executive summary','A decision framework, not a claim that one strategy is guaranteed to maximize profit.',notice+'''<h2>What matters most</h2><p>The first property is expected to pass through a trust; the other is already owned and may provide a place to live without giving up existing rental income. That makes living in the inherited home an opportunity-cost decision, not a need to acquire housing. It does not establish that staying is cost-free or that the existing rent is guaranteed.</p><p><strong>Provisional direction:</strong> compare a prompt sale and diversified investment against renting and occupying; do not treat any as the best plan until the trust, tax basis, assessments, operating costs and household objectives have been verified privately. A prior version asserted that selling was best on the basis of unverified assumptions and an incomplete tax model; that conclusion has been withdrawn.</p>'''+table(['Decision factor','Why it matters'],[(('Property tax','A change in ownership may reset value; an eligible family-home exclusion can reduce the increase.'),['prop13','boe']),(('Estate tax','The exclusion applies to an estate, not independently to each beneficiary; prior taxable gifts and other assets matter.'),['estate','irs']),(('Investment and rental taxes','Capital gains, rental income, depreciation, vacancy, selling costs and state taxes affect comparability.'),['rental','gain','income']),(('Uncertainty','Future rates, laws, market returns and insurance premiums are not known today.'),['cbo','ins'])]))
page('property-tax','Property tax & assessment','The applicable parcel assessment and tax bill are deliberately not reproduced here.',notice+table(['Topic','Rule or status'],[(('Proposition 13','The general property tax levy is 1% of assessed value; other voter-approved debt and charges can apply. Assessed values generally rise by no more than 2% per year absent reassessment or other adjustments.'),['prop13']),(('Family-home exclusion','Eligibility depends on the relationship and the transferor’s and eligible transferee’s principal residence. The transferee must occupy within one year and continue to qualify.'),['boe']),(('Value limit for current period','For transfers from 16 February 2025 through 15 February 2027, the allowance is approximately $1,044,590 above the factored base-year value; the actual official amount is in the linked notice. Future allowance is unknown.'),['cap']),(('Case-specific assessments and bills',''),['prop13']),(('Trust transfer date and reassessment',''),['boe'])])+'''<p>When eligible, if the market value exceeds the factored base-year value plus the allowance, the excess is added to the base-year value. Confirm ownership changes and the relevant date with the assessor; trust transfers are fact-specific.</p>''')
page('projections','Year-by-year projections','Dollar estimates based on unverified private records are intentionally withheld.',notice+table(['Year','Market value','Assessed value','Property tax','Operating costs'],[((str(y),'','','',''),['prop13','insdata']) for y in range(2026,2056)])+'''<p>Blank is not zero. No official source establishes a future parcel-specific value. See <a href="black-swan-scenarios.html">Black-swan scenarios</a> for a fully specified hypothetical index rather than a personalized forecast.</p>''')
page('operating-costs','Operating costs','Budget each property separately; a statewide benchmark is not a household quote.',notice+table(['Item','Verified amount / treatment'],[(('Homeowners insurance statewide average','Approximately $1,570 per year, rounded; published state average, not a current property quote or landlord premium.'),['ins']),(('Owner-occupied and landlord-policy premiums',''),['insdata']),(('Water and electricity bills',''),['solar']),(('Solar export compensation or net credit',''),['solar']),(('Repairs, capital replacement, vacancy and management',''),['rental']),(('Existing rental income',''),['rental','rent'])])+'''<p>Quotes depend on replacement cost, deductibles, occupancy, coverage, location and insurer. Confirm the solar tariff, annual true-up and whether credits are actually payable. Use a landlord policy where appropriate; do not substitute the statewide homeowner average for a quote.</p>''')
page('inheritance-law','Estate & inheritance law','Federal estate tax, California income tax and property tax are separate questions.',table(['Topic','Verified rule / limitation'],[(('Federal estate exclusion','The 2026 basic exclusion is $15,000,000; it is not a separate tax-free amount for every heir. Actual tax depends on the estate and gift history.'),['irs','estate']),(('California income tax','The FTB says gifts and inheritances are generally not included in recipient income; later interest, dividends, rent and gains may be taxable.'),['ca']),(('Inherited basis','Inherited property generally takes fair market value at death, or the alternate valuation date where properly elected; exceptions and trust inclusion matter.'),['basis']),(('California estate tax','The available state analysis describes the state pick-up tax as zero after repeal of the federal credit. Reconfirm current law and special circumstances.'),['pickup']),(('Local estate or inheritance tax',''),['estate'])])+'''<p>Estate tax is generally computed at the estate level, not as a tax penalty for receiving an inheritance. A trust’s terms do not by themselves establish tax treatment or an automatic basis adjustment.</p>''')
page('estate-thresholds','Tax thresholds & headroom','A threshold is not a calculation of this estate’s tax.',table(['Measure','Value or status'],[(('2026 federal basic exclusion','$15,000,000'),['irs']),(('Actual available exclusion after gifts and any portability',''),['estate']),(('Full taxable estate, deductions and cash inheritance',''),['estate']),(('Headroom remaining',''),['estate']),(('2040–2050 exclusion and tax liability',''),['law','irs'])])+'''<p>For private analysis, the professional should assemble worldwide estate assets, lifetime taxable gifts, liabilities, deductions, applicable credits and any properly elected portability. Subtracting only the home value from the exclusion is not a valid calculation of actual headroom. Future indexed amounts are unknown, and Congress may change the law.</p>''')
page('decision-analysis','Decision analysis','Compare net outcomes over the same period, with matched assumptions and explicit tax treatment.',notice+table(['Option','Benefits and costs to investigate'],[(('Occupy inherited home','Possible family-home reassessment exclusion if all requirements are met; costs include tax, insurance, utilities, upkeep and the foregone investment or rental income.'),['boe','prop13']),(('Rent inherited home','Potential rent less vacancy, tax, insurance, maintenance and management; rental income tax, depreciation and later sale consequences matter.'),['rental','prop13']),(('Sell and reinvest','Net proceeds depend on trust authority, sale costs, basis and taxes; portfolios and savings have different risk, liquidity and taxation.'),['basis','gain','income']),(('Already-owned residence','Keep its rent, property costs and housing alternatives consistent across scenarios; do not assume its existing assessment changes solely because the other property is inherited.'),['prop13','rent'])])+'''<h2>Comparison formula</h2><p>For each strategy, compare after-tax net cash flows and the after-tax liquidation value at the same horizon. Consider whether surplus cash is invested, financing, cost of living, time value of money, California tax, estate tax allocation, capital gains, depreciation recapture and risk. No ranking is verifiable with the available official facts.</p>''')
# Hypothetical index paths. A source link provides historical context, not a validation of these assumptions.
base_h = stress_h = base_c = stress_c = 100.0
shock_home={2030:-.20,2031:-.08,2041:-.15,2055:-.25,2056:-.10,2067:-.12}
shock_cpi={2030:.07,2031:.06,2041:.08,2042:.07,2055:.05,2056:.04,2067:.09}
rows=[]
for y in range(2026,2076):
    if y > 2026:
        base_h *= 1.03; stress_h *= 1 + shock_home.get(y,.03)
        base_c *= 1.02; stress_c *= 1 + shock_cpi.get(y,.02)
    rows.append(((str(y),f'{base_h:.1f}',f'{stress_h:.1f}',f'{base_c:.1f}',f'{stress_c:.1f}'),['cpi','fhfa']))
page('black-swan-scenarios','Black-swan economic scenarios','A 50-year index illustrates uneven returns and inflation, not a prediction or estimate of either property.', '''<div class="notice"><strong>Hypothetical, not an official forecast.</strong> Both series start at 100 in 2026. Smooth home prices rise 3% annually and smooth prices rise 2%; stress uses the same defaults except for the shocks listed below. No private financial inputs are used. Source links describe historical context only, not these chosen assumptions.</div><h2>Why stress test?</h2><p>National CPI rose 9.1% in the 12 months ending June 2022, showing that inflation need not be stable. A price index is not a parcel appraisal and history does not predict the next shock.</p>'''+table(['Synthetic shock years','Assumed home change','Assumed inflation'],[((str(y),f'{shock_home.get(y,.03)*100:.0f}%',f'{shock_cpi.get(y,.02)*100:.0f}%'),['cpi','fhfa']) for y in sorted(set(shock_home)|set(shock_cpi))])+'''<h2>Annual index paths · 2026–2075</h2><p>Values are nominal indexes, not dollars. Each year’s index equals the prior index multiplied by one plus that year’s assumed rate. No withdrawals, taxes, reinvestment, property assessment, income or portfolio returns are modeled.</p>'''+table(['Year','Smooth home','Stress home','Smooth prices','Stress prices'],rows))
page('inheritance-process','Step-by-step inheritance process','The trustee and qualified professionals should verify the actual trust and deadlines.',table(['Step','Action'],[(('1 · Before transfer','Review trust documents and title privately; determine who controls and inherits the property.'),['trust']),(('2 · At death','Trustee gives any required statutory notices and secures property, records and coverage.'),['trust']),(('3 · Establish values','Obtain date-of-death valuations and determine federal and California basis and estate inclusion.'),['basis','estate']),(('4 · Notify assessor','Check change-of-ownership forms, applicable due dates and supplemental assessments with the county.'),['prop13']),(('5 · Review exclusion','If the relationship and residence qualify, occupy within one year and file the homeowners’ or disabled veterans’ exemption as required. Check the separate claim deadline and exceptions.'),['boe']),(('6 · Administer taxes','Review final individual, fiduciary and estate tax filing obligations, elections and payments.'),['estate','ca']),(('7 · Decide and document','Compare occupy, rent or sell after verified taxes, insurance, maintenance, liquidity and existing housing are considered.'),['rental','basis'])]))
page('law-watchlist','Law change watchlist','Separate enacted law from proposals, and recheck near the transfer date.',table(['Area','Status and relevance'],[(('Federal exclusion','Public Law 119-21 raised the basic exclusion for 2026 and provides for indexing. Congress can change law; the future figure is not established here.'),['law','irs']),(('California Proposition 19','The intergenerational allowance is adjusted biennially. Eligibility and the transfer-year limit should be verified at the time.'),['boe','cap']),(('San Francisco rent proposal','As of 9 November 2026, the Rent Board reported a proposed limit on certain combined banked and capital-improvement increases; it had not been enacted. Check current status.'),['rent']),(('2026 California election measures',''),['vote'])]))
page('methodology','Methodology & assumptions','Distinguish official rules from private facts and illustrative models.',table(['Principle','Application'],[(('Sources','Links point to official agencies. A source for a model row gives context only and does not verify its assumptions.'),['cpi','fhfa']),(('Unknown figures','Blank means unverified or intentionally withheld, not zero.'),['boe']),(('Money','Displayed dollar figures are rounded to the nearest $10; follow the linked source for exact statutory amounts.'),['cap','ins']),(('Projections','Index paths use explicitly invented rates for illustration, not official forecasts or property-specific values.'),['cpi','fhfa']),(('Recommendation','No quantitative personalized ranking is defensible until private inputs, assumptions and tax treatment are verified.'),['basis','rental'])]))
page('sources','Official source register','A starting point for manual review. An official source does not verify private details or hypothetical assumptions.',table(['Reference','Agency'],[((name, key),[key]) for key,(name,_) in S.items()]))
page('flagged-for-review','Flagged for review','Material uncertainties and corrections that need attention; blanks are intentional.',table(['Flag','Issue / next step'],[(('Privacy exposure','Earlier versions and Git history included case-specific financial details, including unrounded values. This update removes them from the current tree; history, caches, forks and prior deployments may still expose them. Repository-owner remediation is needed.'),['prop13']),(('Previous recommendation withdrawn','The prior sell recommendation used unverified assumptions, incomplete rental and California taxes, and a bond yield as if it were an after-tax savings return. Do not rely on its ranking.'),['rental','gain']),(('Tax bill discrepancy','A supplied tax bill and assessed value are not independently verified. Direct charges and rate-area differences may explain discrepancies; obtain the official bill privately.'),['prop13']),(('Property and household facts','Values, rent, solar credit, assessment history, unit occupancy, relationship, trust terms and cash inheritance are not independently verified and are not published.'),['boe','solar']),(('Insurance','The statewide average is not a quote for either property, particularly not for a rental policy.'),['insdata']),(('Projection limits','No parcel-specific future tax, market price or insurance premium has an official verified value; no personalized forecast or headroom is published.'),['cbo','boe']),(('Transfer and basis','The trust may create different ownership or basis outcomes; eligibility and dates need professional confirmation.'),['boe','basis']),(('GitHub Pages configuration','Root Pages may serve files beyond linked pages if exclusions are changed; public repository history remains independently accessible.'),['boe'])]))
page('privacy','Privacy','The public dashboard excludes case-specific financial inputs and derived dollar projections.', '''<p>Names, addresses, parcel numbers, exact case financial inputs, trust documents and other personal information do not belong in a public repository or website. Rounding to $10 and replacing names alone cannot guarantee anonymity, especially when distinctive figures are combined.</p><p>Earlier commits and published copies may contain sensitive details. Removing them from the latest tree does not remove Git history, forks, caches or past deployments. A repository administrator should assess history removal and exposure through GitHub’s sensitive-data process. Do not place private documents into issues, pull requests, or the task board.</p>'''+table(['Boundary','Public treatment'],[(('Case-specific values and projected dollars','Withheld; unverified values left blank.'),['prop13']),(('Published model','Synthetic indices only, with no household data.'),['cpi']),(('Official facts','Source-linked, with displayed dollar amounts rounded.'),['irs','cap'])]))
# Preserve compatibility with the most common previous URLs, without retaining their content.
for old,new in {'decisions':'decision-analysis','costs':'operating-costs','properties':'property-tax','flagged':'flagged-for-review'}.items():
    (PAGES/(old+'.html')).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta http-equiv="refresh" content="0; url={new}.html"><title>Page moved</title></head><body><a href="{new}.html">Continue to the updated page</a></body></html>',encoding='utf-8')
print('Built',len(NAV),'dashboard pages and 4 compatibility redirects')
